using System.Collections.Generic;using UnityEngine;using Alterverse.Characters;using Alterverse.Combat;
namespace Alterverse.Match
{
public sealed class MatchTelemetry:MonoBehaviour
{
public sealed class HeroStats{public HeroId Hero;public int Team;public float DamageDealt,DamageTaken,Healing,FrontContribution;public int Kills,Deaths,Assists,Objectives,HotZoneCaptures,SoldierKills;public float MvpScore=>Kills*110+Assists*85-Deaths*25+DamageDealt*.085f+DamageTaken*.04f+Healing*.14f+FrontContribution*42f;}public static MatchTelemetry Instance{get;private set;}private readonly Dictionary<Health,HeroStats> stats=new();private DimensionsFront front;private bool summaryLogged;private float nextBind;public IEnumerable<HeroStats> Stats=>stats.Values;
private void Awake(){if(Instance!=null&&Instance!=this){Destroy(gameObject);return;}Instance=this;}private void Start(){TryBindFront();}private void Update(){if(front!=null||Time.unscaledTime<nextBind)return;nextBind=Time.unscaledTime+.5f;TryBindFront();}private void TryBindFront(){DimensionsFront found=FindAnyObjectByType<DimensionsFront>();if(found==null||found==front)return;if(front!=null)front.MatchEnded-=OnMatchEnded;front=found;front.MatchEnded+=OnMatchEnded;}private void OnDestroy(){if(front!=null)front.MatchEnded-=OnMatchEnded;if(Instance==this)Instance=null;}
public HeroStats Get(Health health){if(health==null)return null;if(stats.TryGetValue(health,out HeroStats s))return s;HeroIdentity id=health.GetComponent<HeroIdentity>();TeamMember tm=health.GetComponent<TeamMember>();if(id==null||tm==null)return null;s=new HeroStats{Hero=id.Hero,Team=tm.Team};stats.Add(health,s);return s;}public void RecordDamage(Health victim,GameObject source,float amount){if(victim==null||source==null||amount<=0)return;Health attacker=source.GetComponentInParent<Health>();if(attacker==null||attacker==victim)return;TeamMember victimTeam=victim.GetComponent<TeamMember>(),attackerTeam=attacker.GetComponent<TeamMember>();if(victimTeam!=null&&attackerTeam!=null&&victimTeam.Team==attackerTeam.Team)return;HeroStats v=Get(victim),a=Get(attacker);if(v!=null)v.DamageTaken+=amount;if(a!=null)a.DamageDealt+=amount;}public void RecordHealing(Health target,float amount){HeroStats s=Get(target);if(s!=null&&amount>0)s.Healing+=amount;}public void RecordAssist(Health assistant){HeroStats s=Get(assistant);if(s!=null)s.Assists++;}public void RecordDeath(Health victim,GameObject source){HeroStats v=Get(victim);if(v!=null)v.Deaths++;Health killer=source!=null?source.GetComponentInParent<Health>():null;HeroStats k=Get(killer);if(k!=null&&k!=v){k.Kills++;if(victim.GetComponent<LaneMinion>()!=null||victim.GetComponent<TrenchSoldier>()!=null)k.SoldierKills++;}}public void RecordHotZoneCapture(Health hero){HeroStats s=Get(hero);if(s!=null)s.HotZoneCaptures++;}public void RecordFrontContribution(GameObject source,float amount){if(source==null||amount<=0)return;HeroStats s=Get(source.GetComponentInParent<Health>());if(s!=null)s.FrontContribution+=amount;}public void RecordObjective(GameObject source,float frontAmount){if(source==null)return;HeroStats s=Get(source.GetComponentInParent<Health>());if(s==null)return;s.Objectives++;if(frontAmount>0)s.FrontContribution+=frontAmount;}public HeroStats GetStats(Health health)=>Get(health);private void OnMatchEnded(int winner){LogSummary(winner);}
public void LogSummary(int winner=-1){if(summaryLogged)return;summaryLogged=true;
#if UNITY_EDITOR || DEBUG
float zero=front!=null?front.ZeroControl:50,lumen=front!=null?front.LumenControl:50;Debug.Log($"[DIMENSIONS FRONT BALANCE] MATCH END winner={(winner<0?"unknown":winner.ToString())} ZERO {zero:0.0} / LUMEN {lumen:0.0}");foreach(HeroStats s in stats.Values)Debug.Log($"[DIMENSIONS FRONT BALANCE] T{s.Team} {s.Hero} K{s.Kills}/D{s.Deaths}/A{s.Assists} OBJ {s.Objectives} DMG {s.DamageDealt:0} TAKEN {s.DamageTaken:0} HEAL {s.Healing:0} FRONT {s.FrontContribution:0.0} MVP {s.MvpScore:0}");
#endif
}
}
}
